// @ts-nocheck — generated by catalog-eject; runtime-correct but TS strict-mode false-positives on inlined catalog body
import { useRef } from "react";
import { motion, useScroll, useTransform } from "motion/react";
import ImageOrVideo from "@/components/ui/ImageOrVideo";

type FeaturesParallaxShowcaseProps = {
  title: string;
  leftImageSrc: string;
  rightImageSrc: string;
} & ({ backgroundSrc: string; backgroundVideoSrc?: never } | { backgroundVideoSrc: string; backgroundSrc?: never });

const ShowcaseInline = () => {
  const sectionRef = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: sectionRef,
    offset: ["start end", "end start"],
  });

  const leftY = useTransform(scrollYProgress, [0, 1], ["-10%", "20%"]);
  const leftRotate = useTransform(scrollYProgress, [0, 1], [-13, 8]);
  const rightY = useTransform(scrollYProgress, [0, 1], ["-5%", "25%"]);
  const rightRotate = useTransform(scrollYProgress, [0, 1], [6, -7]);

  return (
    <section
      ref={sectionRef}
      aria-label="Parallax showcase section"
      className="relative w-full h-svh overflow-hidden my-20"
    >
      <div className="absolute inset-0">
        <ImageOrVideo imageSrc={"https://storage.googleapis.com/webild/users/user_3AniccObAoDJgCkSlT6RJk7a8NL/uploaded-1783298594478-tsnq7pa3.webp"} className="w-full h-full object-cover" />
      </div>

      <div className="relative z-10 w-full pt-32 md:pt-48 text-center">
        <h2 className="text-7xl md:text-8xl text-white font-serif">
          {"For a Strong Switzerland \n                  🇨🇭"}
        </h2>
      </div>

      <motion.div
        style={{ y: leftY, rotate: leftRotate }}
        className="absolute left-[5%] md:left-[12%] top-[28%] md:top-[2%] w-[50vw] md:w-[26vw] max-w-[420px] drop-shadow-2xl pointer-events-none"
      >
        <ImageOrVideo imageSrc={"https://storage.googleapis.com/webild/users/user_3AniccObAoDJgCkSlT6RJk7a8NL/uploaded-1783294133902-jfwtklo3.jpg"} className="w-full h-auto" />
      </motion.div>
    </section>
  );
};

export default function ShowcaseSection() {
  return (
    <div data-webild-section="showcase" data-section="showcase" id="showcase">
      <ShowcaseInline />
    </div>
  );
}
